sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform shader blurred;
uniform shader backdrop;
uniform float blur;
uniform float refraction;
uniform float frost;
uniform float dispersion;
uniform float angle;
uniform float highlight;
layout(color) uniform half4 color;
uniform float tint;
float h(float2 p) { return float(blurred.eval(p).a); }
float4 frosted(float2 p) {
    float4 s = float4(backdrop.eval(p));
    if (frost < 0.5) return s;
    s *= 0.2;
    for (int i = 0; i < 8; i++) {
        float a = float(i) * 0.7853982;
        float r = frost * (fract(float(i) * 0.5) < 0.25 ? 1.0 : 0.55);
        s += float4(backdrop.eval(p + float2(cos(a), sin(a)) * r)) * 0.1;
    }
    return s;
}
half4 main(float2 coord) {
    half4 src = image.eval(coord);
    if (src.a <= 0.0) return half4(0.0);
    float e = max(blur * 0.15, 1.0);
    float2 g = float2(h(coord + float2(e, 0.0)) - h(coord - float2(e, 0.0)), h(coord + float2(0.0, e)) - h(coord - float2(0.0, e))) / (2.0 * e);
    float3 n = normalize(float3(-g * max(blur, 1.0), 1.0));
    float edge = clamp(length(n.xy), 0.0, 1.0);
    float2 bend = -n.xy * refraction * (0.35 + 0.65 * edge);
    float k = clamp(dispersion, 0.0, 1.0) * 0.6 * edge;
    float4 mid = frosted(coord + bend);
    float4 bg = float4(frosted(coord + bend * (1.0 + k)).r, mid.g, frosted(coord + bend * (1.0 - k)).b, mid.a);
    float3 rgb = bg.a > 0.0 ? clamp(bg.rgb / bg.a, 0.0, 1.0) : float3(color.rgb);
    float amount = clamp(tint, 0.0, 1.0) * float(color.a);
    rgb = mix(rgb, float3(color.rgb), amount);
    float a = radians(angle);
    float2 toward = float2(cos(a), -sin(a));
    float3 l = normalize(float3(toward, 0.6));
    float spec = pow(max(dot(reflect(-l, n), float3(0.0, 0.0, 1.0)), 0.0), 40.0);
    float facing = edge > 0.001 ? dot(n.xy / edge, toward) : 0.0;
    float rim = pow(edge, 3.0) * (0.9 * max(facing, 0.0) + 0.45 * max(-facing, 0.0));
    float shine = clamp((spec * 0.6 + rim) * highlight, 0.0, 1.0);
    float alpha = max(max(float(bg.a), shine), amount * 0.6);
    rgb = clamp(rgb * max(float(bg.a), amount * 0.6) / max(alpha, 0.001) + shine, 0.0, 1.0);
    return half4(half3(rgb * alpha), half(alpha)) * src.a;
}
